package com.ateliercampus.dao;
import java.sql.*;import java.util.*;import java.time.*;
public class InscriptionDao {
 public void inscrire(long etu,long atelier)throws Exception{try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("SELECT date_heure,capacite FROM Atelier WHERE id=? FOR UPDATE")){p.setLong(1,atelier);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Atelier introuvable.");if(!r.getTimestamp(1).toLocalDateTime().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Les inscriptions sont closes : l’atelier a commencé.");int cap=r.getInt(2);try(PreparedStatement n=c.prepareStatement("SELECT COUNT(*) FROM Inscription WHERE atelier_id=? AND statut='CONFIRMEE'")){n.setLong(1,atelier);try(ResultSet q=n.executeQuery()){q.next();if(q.getInt(1)>=cap)throw new IllegalArgumentException("Atelier complet.");}}}}
 try(PreparedStatement p=c.prepareStatement("SELECT statut FROM Inscription WHERE etudiant_id=? AND atelier_id=?")){p.setLong(1,etu);p.setLong(2,atelier);try(ResultSet r=p.executeQuery()){if(r.next()){if("CONFIRMEE".equals(r.getString(1)))throw new IllegalArgumentException("Vous êtes déjà inscrit à cet atelier.");try(PreparedStatement u=c.prepareStatement("UPDATE Inscription SET statut='CONFIRMEE',date_inscription=CURRENT_TIMESTAMP WHERE etudiant_id=? AND atelier_id=?")){u.setLong(1,etu);u.setLong(2,atelier);u.executeUpdate();}}else try(PreparedStatement i=c.prepareStatement("INSERT INTO Inscription(etudiant_id,atelier_id,date_inscription,statut) VALUES(?,?,CURRENT_TIMESTAMP,'CONFIRMEE')")){i.setLong(1,etu);i.setLong(2,atelier);i.executeUpdate();}}}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public void annuler(long etu,long id)throws Exception{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE Inscription SET statut='ANNULEE' WHERE id=? AND etudiant_id=? AND statut='CONFIRMEE' AND atelier_id IN(SELECT id FROM Atelier WHERE date_heure>CURRENT_TIMESTAMP)")){p.setLong(1,id);p.setLong(2,etu);if(p.executeUpdate()!=1)throw new IllegalArgumentException("Annulation impossible : inscription absente, non confirmée ou atelier commencé.");}}
 public List<Map<String,Object>> pourEtudiant(long id)throws Exception{return query("SELECT i.id AS \"id\",i.statut AS \"statut\",i.date_inscription AS \"date_inscription\",a.id AS \"atelier_id\",a.titre AS \"titre\",a.date_heure AS \"date_heure\",a.capacite AS \"capacite\",(SELECT COUNT(*) FROM Inscription x WHERE x.atelier_id=a.id AND x.statut='CONFIRMEE') AS \"inscrits\" FROM Inscription i JOIN Atelier a ON a.id=i.atelier_id WHERE i.etudiant_id=? ORDER BY a.date_heure",id);}
 public List<Map<String,Object>> participants(long id)throws Exception{return query("SELECT i.id AS \"id\",i.statut AS \"statut\",e.nom AS \"nom\",e.email AS \"email\" FROM Inscription i JOIN Etudiant e ON e.id=i.etudiant_id WHERE i.atelier_id=? ORDER BY i.date_inscription",id);}
 private List<Map<String,Object>> query(String sql,long id)throws Exception{List<Map<String,Object>> out=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){ResultSetMetaData m=r.getMetaData();while(r.next()){Map<String,Object>x=new LinkedHashMap<>();for(int n=1;n<=m.getColumnCount();n++)x.put(m.getColumnLabel(n),r.getObject(n));out.add(x);}}}return out;}
}
